import React, { useEffect, useState } from "react";
import { useParams, useHistory } from "react-router-dom";
import { updateCar, getCarById } from "../../services/ApiCar"; // Assure-toi de créer cette fonction API

export default function CardUpdateVoiture() {
  const { id } = useParams();
  const history = useHistory();
  const [car, setCar] = useState({
    matricule: "",
    model: "",
    marque: "",
    libelle: "",
    prix: "",
    prix_jour: "",
    couleur: "",
    disponible: false,
    voiture_image: null,
  });
  const [errors, setErrors] = useState({});
  const [loading, setLoading] = useState(true); // Ajout d'un état de chargement
  const [submitLoading, setSubmitLoading] = useState(false); // État pour le chargement de la soumission

  useEffect(() => {
    const fetchCar = async () => {
      try {
        const res = await getCarById(id); // Utilise une fonction pour récupérer directement une voiture par son id
        if (res.data) {
          setCar({
            ...res.data,
            voiture_image: null, // reset image
          });
        } else {
          alert("Voiture non trouvée !");
          history.push("/admin/Voiture");
        }
      } catch (err) {
        console.error(err);
        alert("Erreur de récupération des données");
        history.push("/admin/Voiture");
      } finally {
        setLoading(false); // Met à jour l'état du chargement
      }
    };

    fetchCar();
  }, [id, history]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setCar({ ...car, [name]: value });
    setErrors({}); // Réinitialiser les erreurs lorsque l'utilisateur modifie un champ
  };

  const handleFileChange = (e) => {
    const file = e.target.files[0];
    const allowedTypes = ["image/jpeg", "image/png"];

    if (file && !allowedTypes.includes(file.type)) {
      alert("Seules les images JPG ou PNG sont autorisées.");
    } else {
      setCar({ ...car, voiture_image: file || null });
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    let formErrors = {};

    // Validation des champs
    if (!car.matricule.trim()) formErrors.matricule = "Matricule requis";
    if (!car.model.trim()) formErrors.model = "Modèle requis";
    if (!car.marque.trim()) formErrors.marque = "Marque requise";
    if (!car.libelle.trim()) formErrors.libelle = "Libellé requis";
    if (!car.prix || parseFloat(car.prix) <= 0) formErrors.prix = "Prix requis et doit être supérieur à zéro";
    if (!car.prix_jour || parseFloat(car.prix_jour) <= 0) formErrors.prix_jour = "Prix par jour requis et doit être supérieur à zéro";
    if (!car.couleur.trim()) formErrors.couleur = "Couleur requise";

    if (Object.keys(formErrors).length > 0) {
      setErrors(formErrors);
      return;
    }

    setSubmitLoading(true); // Démarre le chargement lors de la soumission

    const formData = new FormData();
    for (const key in car) {
      if (car[key] !== null) {
        formData.append(key, car[key]);
      }
    }

    try {
      await updateCar(formData, id);
      history.push("/admin/Voiture");
    } catch (error) {
      if (error.response && error.response.data) {
        setErrors(error.response.data.errors); // Gérer les erreurs retournées par le serveur
      } else {
        console.error("Erreur lors de la mise à jour:", error);
        alert("Erreur lors de la mise à jour de la voiture");
      }
    } finally {
      setSubmitLoading(false); // Fin du chargement de la soumission
    }
  };

  if (loading) {
    return <div>Chargement...</div>; // Afficher un message de chargement pendant la récupération des données
  }

  return (
    <div className="relative flex flex-col min-w-0 break-words w-full mb-6 shadow-lg rounded-lg bg-blueGray-100 border-0">
      <div className="rounded-t bg-white mb-0 px-6 py-6">
        <div className="text-center flex justify-between">
          <h6 className="text-blueGray-700 text-xl font-bold">Modifier la voiture</h6>
          <button
            className="bg-lightBlue-500 text-white font-bold uppercase text-xs px-4 py-2 rounded shadow hover:shadow-md"
            type="button"
            onClick={() => history.push("/admin/Voiture")}
          >
            Retour
          </button>
        </div>
      </div>

      <div className="flex-auto px-4 lg:px-10 py-10 pt-0">
        <form onSubmit={handleSubmit}>
          <h6 className="text-blueGray-400 text-sm mt-3 mb-6 font-bold uppercase">
            Informations véhicule
          </h6>

          <div className="flex flex-wrap">
            {[ // Champs texte avec erreurs dynamiques
              { label: "Matricule", name: "matricule" },
              { label: "Modèle", name: "model" },
              { label: "Marque", name: "marque" },
              { label: "Libellé", name: "libelle" },
              { label: "Prix (€)", name: "prix", type: "number" },
              { label: "Prix/jour (€)", name: "prix_jour", type: "number" },
              { label: "Couleur", name: "couleur" },
            ].map((field, idx) => (
              <div className="w-full lg:w-6/12 px-4" key={idx}>
                <div className="relative w-full mb-3">
                  <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">
                    {field.label}
                  </label>
                  <input
                    type={field.type || "text"}
                    name={field.name}
                    value={car[field.name]}
                    onChange={handleChange}
                    className={`border-0 px-3 py-3 placeholder-blueGray-300 text-blueGray-600 bg-white rounded text-sm shadow w-full ${errors[field.name] ? "border border-red-500" : ""}`}
                    placeholder={field.label}
                  />
                  {errors[field.name] && (
                    <p className="text-red-500 text-xs italic mt-1">{errors[field.name]}</p>
                  )}
                </div>
              </div>
            ))}

            <div className="w-full lg:w-6/12 px-4">
              <div className="relative w-full mb-3 mt-6">
                <label className="inline-flex items-center">
                  <input
                    type="checkbox"
                    name="disponible"
                    checked={car.disponible}
                    onChange={(e) => setCar({ ...car, disponible: e.target.checked })}
                    className="form-checkbox h-5 w-5 text-lightBlue-600 rounded"
                  />
                  <span className="ml-2 text-blueGray-600 font-bold uppercase text-xs">
                    Disponible immédiatement
                  </span>
                </label>
              </div>
            </div>

            <div className="w-full lg:w-6/12 px-4">
              <div className="relative w-full mb-3">
                <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">
                  Image du véhicule (facultative)
                </label>
                <input
                  type="file"
                  name="voiture_image"
                  onChange={handleFileChange}
                  accept="image/*"
                  className="border-0 px-3 py-3 text-blueGray-600 bg-white rounded text-sm shadow w-full"
                />
                {car.voiture_image && (
                  <div className="mt-2">
                    <img src={URL.createObjectURL(car.voiture_image)} alt="Current car image" className="w-32 h-32 object-cover" />
                  </div>
                )}
              </div>
            </div>
          </div>

          <div className="text-center mt-6">
            <button
              type="submit"
              className={`${
                submitLoading ? "opacity-50 cursor-not-allowed" : "bg-lightBlue-500"
              } text-white active:bg-lightBlue-600 font-bold uppercase text-xs px-6 py-3 rounded shadow hover:shadow-md outline-none focus:outline-none mr-1 ease-linear transition-all duration-150`}
              disabled={submitLoading}
            >
              {submitLoading ? "Enregistrement..." : "Enregistrer les modifications"}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}
